import 'dart:io';import 'package:html/parser.dart';
void main(){for(final name in ['flv_new_home','flv_new_detail','flv_new_search']){final d=parse(File('tool/fixtures/$name.html').readAsStringSync());stdout.writeln('\n$name');for(final s in d.querySelectorAll('script[type="application/json"]')){stdout.writeln('JSON ${s.id}');}for(final a in d.querySelectorAll('a[href]').where((a)=>(a.attributes['href']??'').contains('dark-machine')||a.querySelector('h3,h2')!=null).take(12)){final t=a.text.trim().replaceAll(RegExp(r'\s+'),' ');stdout.writeln('LINK parent=${a.parent?.classes} ${t.length>85?t.substring(0,85):t} -> ${a.attributes['href']} IMG=${a.querySelector("img")?.attributes["src"]}');}for(final e in d.querySelectorAll('iframe,video,source,[data-src],[data-video]')){stdout.writeln('MEDIA ${e.outerHtml.substring(0,e.outerHtml.length<250?e.outerHtml.length:250)}');}}}
